import {
  Editable as EditablePrimitive,
  useEditable,
  useEditableContext,
} from '@ark-ui/solid/editable';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, Show, splitProps } from 'solid-js';
import { CheckIcon, CloseIcon, PencilIcon } from '@/lib/moduix/icons/ui';
import styles from './Editable.module.css';

function Editable(props: ComponentProps<typeof EditablePrimitive.Root>) {
  const [local, others] = splitProps(props, ['activationMode', 'class']);

  return (
    <EditablePrimitive.Root
      activationMode={local.activationMode ?? 'dblclick'}
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="editable-root"
    />
  );
}

function EditableRootProvider(props: ComponentProps<typeof EditablePrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="editable-root-provider"
    />
  );
}

function EditableLabel(props: ComponentProps<typeof EditablePrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="editable-label"
    />
  );
}

function EditableArea(props: ComponentProps<typeof EditablePrimitive.Area>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Area
      class={clsx(styles.area, local.class)}
      {...others}
      data-slot="editable-area"
    />
  );
}

function EditableInput(props: ComponentProps<typeof EditablePrimitive.Input>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Input
      class={clsx(styles.input, local.class)}
      {...others}
      data-slot="editable-input"
    />
  );
}

function EditablePreview(props: ComponentProps<typeof EditablePrimitive.Preview>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Preview
      class={clsx(styles.preview, local.class)}
      {...others}
      data-slot="editable-preview"
    />
  );
}

function EditableControl(props: ComponentProps<typeof EditablePrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <EditablePrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="editable-control"
    />
  );
}

function EditableEditTrigger(props: ComponentProps<typeof EditablePrimitive.EditTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <EditablePrimitive.EditTrigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="editable-edit-trigger"
    >
      {resolvedChildren() ?? <PencilIcon />}
    </EditablePrimitive.EditTrigger>
  );
}

function EditableSubmitTrigger(props: ComponentProps<typeof EditablePrimitive.SubmitTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <EditablePrimitive.SubmitTrigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="editable-submit-trigger"
    >
      {resolvedChildren() ?? <CheckIcon />}
    </EditablePrimitive.SubmitTrigger>
  );
}

function EditableCancelTrigger(props: ComponentProps<typeof EditablePrimitive.CancelTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <EditablePrimitive.CancelTrigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="editable-cancel-trigger"
    >
      {resolvedChildren() ?? <CloseIcon />}
    </EditablePrimitive.CancelTrigger>
  );
}

function EditableControls(
  props: Omit<ComponentProps<typeof EditablePrimitive.Control>, 'asChild' | 'children'>,
) {
  const editable = useEditableContext();

  return (
    <EditableControl {...props}>
      <Show when={editable().editing} fallback={<EditableEditTrigger />}>
        <EditableSubmitTrigger />
        <EditableCancelTrigger />
      </Show>
    </EditableControl>
  );
}

const EditableContext = EditablePrimitive.Context;

export {
  Editable,
  EditableArea,
  EditableCancelTrigger,
  EditableContext,
  EditableControl,
  EditableControls,
  EditableEditTrigger,
  EditableInput,
  EditableLabel,
  EditablePreview,
  EditableRootProvider,
  EditableSubmitTrigger,
  useEditable,
  useEditableContext,
};

export type {
  EditableAreaProps,
  EditableCancelTriggerProps,
  EditableContextProps,
  EditableControlProps,
  EditableEditChangeDetails,
  EditableEditTriggerProps,
  EditableFocusOutsideEvent,
  EditableInputProps,
  EditableInteractOutsideEvent,
  EditableLabelProps,
  EditablePointerDownOutsideEvent,
  EditablePreviewProps,
  EditableRootProps,
  EditableRootProviderProps,
  EditableSubmitTriggerProps,
  EditableValueChangeDetails,
  UseEditableContext,
  UseEditableProps,
  UseEditableReturn,
} from '@ark-ui/solid/editable';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
    gap: var(--moduix-spacing-1);
    width: 100%;
    color: var(--moduix-color-foreground);

    &:has([data-autoresize]) {
      width: fit-content;
      max-width: 100%;
    }

    &:has([data-disabled]) {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  .label {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    overflow-wrap: anywhere;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);

    &[data-invalid] {
      color: var(--moduix-color-destructive);
    }
  }

  .area {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    min-width: 0;
    min-height: var(--moduix-editable-area-height, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3-5);
    background-color: var(--moduix-color-background);
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &:is([data-focus], :has(:focus-visible)) {
      outline-color: var(--moduix-color-ring);
    }

    &:has([data-invalid]) {
      border-color: var(--moduix-color-destructive);

      &:is([data-focus], :has(:focus-visible)) {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .input,
  .preview {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    margin: 0;
    border: 0;
    padding: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    outline: 0;
  }

  .input {
    appearance: none;

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &:is(textarea) {
      min-height: 6rem;
      resize: vertical;
    }
  }

  .preview {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    cursor: text;

    &[data-placeholder-shown] {
      color: var(--moduix-color-muted-foreground);
    }

    &:is([data-disabled], [aria-readonly='true']) {
      cursor: default;
    }
  }

  .control {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: var(--moduix-editable-area-height, var(--moduix-size-md));
    height: var(--moduix-editable-area-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-sm);
    padding: 0;
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active {
      background-color: var(--moduix-color-accent);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &:disabled {
      pointer-events: none;
    }

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
      flex-shrink: 0;
    }
  }
}
